<?php
declare(strict_types=1);
require __DIR__.'/../app/services/CourseEditService.php';
class CourseWaitingTestPDO extends PDO { public function prepare(string $sql,array $options=[]): PDOStatement|false { return parent::prepare(str_replace(' FOR UPDATE','',$sql),$options); } }
$db=new CourseWaitingTestPDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec("CREATE TABLE rooms (id INTEGER PRIMARY KEY,name TEXT); CREATE TABLE courses (id INTEGER PRIMARY KEY,title TEXT,room_id INTEGER,coach_id INTEGER,starts_at TEXT,ends_at TEXT,capacity INTEGER,status TEXT); CREATE TABLE private_sessions (id INTEGER PRIMARY KEY,member_id INTEGER,status TEXT,starts_at TEXT,ends_at TEXT); CREATE TABLE members (id INTEGER PRIMARY KEY,status TEXT); CREATE TABLE subscriptions (id INTEGER PRIMARY KEY,member_id INTEGER,status TEXT,start_date TEXT,end_date TEXT); CREATE TABLE course_bookings (id INTEGER PRIMARY KEY,course_id INTEGER,member_id INTEGER,status TEXT,created_at TEXT); CREATE TABLE activity_logs (user_id INTEGER,action TEXT,ip_address TEXT); INSERT INTO rooms VALUES (1,'Salle A'),(2,'Salle B'); INSERT INTO courses VALUES (1,'Yoga',1,NULL,'2030-05-01 10:00:00','2030-05-01 11:00:00',1,'scheduled'),(2,'Boxe',2,NULL,'2030-05-01 10:30:00','2030-05-01 11:30:00',5,'scheduled'); INSERT INTO members VALUES (1,'active'),(2,'active'),(3,'active'); INSERT INTO subscriptions VALUES (1,1,'active','2030-01-01','2030-12-31'),(2,2,'active','2030-01-01','2030-12-31'),(3,3,'active','2030-01-01','2030-12-31'); INSERT INTO course_bookings VALUES (1,1,3,'confirmed','2029-01-01'),(2,1,1,'waiting','2029-01-02'),(3,1,2,'waiting','2029-01-03'),(4,2,1,'confirmed','2029-01-01');");
$course=$db->query('SELECT * FROM courses WHERE id=1')->fetch();
$input=['title'=>'Yoga','room_id'=>'1','coach_id'=>'','starts_at'=>'2030-05-01T10:00','ends_at'=>'2030-05-01T11:00','capacity'=>'2'];
$count=(new CourseEditService($db,1,'',new DateTimeImmutable('2029-01-01')))->edit(1,CourseEditService::version($course),$input);
if ($count!==1 || $db->query('SELECT status FROM course_bookings WHERE id=2')->fetchColumn()!=='waiting' || $db->query('SELECT status FROM course_bookings WHERE id=3')->fetchColumn()!=='confirmed') throw new RuntimeException('Promotion lors de l’augmentation de capacité incorrecte');
echo "Cours : promotion sur capacité avec conflit d’un autre cours OK\n";
